"""Real loopback HTTP transport, generated bytes only; no models/network service."""
from contextlib import contextmanager
import hashlib
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import os
from pathlib import Path
import tempfile
import threading
import time
import unittest
from unittest.mock import patch

from core.downloader import download_with_progress
from core.render_context import RenderContext, RenderCancelled, bind_job

PAYLOAD = b'reflow-generated-transport-fixture' * 8192


@contextmanager
def server():
    class Handler(BaseHTTPRequestHandler):
        def log_message(self, *args):
            pass

        def do_GET(self):
            self.send_response(200)
            self.send_header('Content-Type', 'application/octet-stream')
            self.send_header('Content-Length', str(len(PAYLOAD) + (1 if self.path == '/truncated' else 0)))
            self.end_headers()
            try:
                for offset in range(0, len(PAYLOAD), 32768):
                    self.wfile.write(PAYLOAD[offset:offset + 32768])
                    self.wfile.flush()
                    if self.path == '/slow':
                        time.sleep(.1)
            except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
                pass
    http = ThreadingHTTPServer(('127.0.0.1', 0), Handler)
    thread = threading.Thread(target=http.serve_forever, daemon=True)
    thread.start()
    try:
        with patch.dict(os.environ, {'NO_PROXY': '127.0.0.1', 'REFLOW_OFFLINE': '0'}):
            yield 'http://127.0.0.1:' + str(http.server_port)
    finally:
        http.shutdown(); http.server_close(); thread.join(timeout=5)


class DownloadTransportTests(unittest.TestCase):
    def test_complete_transfer_verifies_and_publishes_generated_bytes(self):
        with tempfile.TemporaryDirectory() as folder, server() as url:
            target = Path(folder) / 'fixture.bin'
            reports = list(download_with_progress(url + '/complete', str(target),
                expected_size=len(PAYLOAD), expected_sha256=hashlib.sha256(PAYLOAD).hexdigest()))
            self.assertEqual(target.read_bytes(), PAYLOAD)
            self.assertEqual(reports[-1]['phase'], 'done')
            self.assertEqual(reports[-1]['downloaded'], len(PAYLOAD))

    def test_truncated_response_cannot_replace_existing_file(self):
        with tempfile.TemporaryDirectory() as folder, server() as url:
            target = Path(folder) / 'fixture.bin'; target.write_bytes(b'accepted existing file')
            reports = []
            with self.assertRaises(Exception):
                for report in download_with_progress(url + '/truncated', str(target)):
                    reports.append(report)
            self.assertEqual(target.read_bytes(), b'accepted existing file')
            self.assertFalse(any(report['phase'] == 'done' for report in reports))
            self.assertFalse(list(Path(folder).glob('.model-download-*.tmp')))

    def test_cancel_stream_preserves_existing_file_without_publishing_completion(self):
        with tempfile.TemporaryDirectory() as folder, server() as url:
            target = Path(folder) / 'fixture.bin'; target.write_bytes(b'accepted existing file')
            job = RenderContext(Path(folder) / 'temp')
            try:
                with bind_job(job):
                    transfer = download_with_progress(url + '/slow', str(target), chunk_size=4096)
                    try:
                        self.assertEqual(next(transfer)['phase'], 'downloading')
                        job.request_stop()
                        with self.assertRaises(RenderCancelled):
                            next(transfer)
                    finally:
                        transfer.close()
                self.assertEqual(target.read_bytes(), b'accepted existing file')
                self.assertFalse(list(Path(folder).glob('.model-download-*.tmp')))
            finally:
                job.cleanup()


if __name__ == '__main__':
    unittest.main()
